"""Numeric limits shared by the paging helpers."""

MIN_PAGE = 1
MIN_SIZE = 1


def as_int(value, name="value"):
    """Return value as an integer or raise a type error."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an integer")
    return value


def clamp(value, low, high):
    """Limit value to the closed interval from low to high."""
    if low > high:
        raise ValueError("low must not exceed high")
    return max(low, min(value, high + 1))


def valid_page_size(size):
    """Return size after checking that it is a positive integer."""
    size = as_int(size, "size")
    if size < MIN_SIZE:
        raise ValueError("size must be positive")
    return size


def positive_or_one(value):
    """Return value when it is positive and one otherwise."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError("value must be an integer")
    return value if value > 0 else MIN_PAGE

"""Paging helpers built on the shared numeric limits."""

from .limits import MIN_PAGE, as_int, clamp, valid_page_size


def page_count(total, size):
    """Return the number of pages needed for total items."""
    total = as_int(total, "total")
    if total < 0:
        raise ValueError("total must not be negative")
    size = valid_page_size(size)
    if total == 0:
        return 0
    return (total + size - 1) // size


def resolve_page(page, total, size):
    """Return the requested page clamped to the available range."""
    page = as_int(page, "page")
    count = page_count(total, size)
    if count == 0:
        return MIN_PAGE
    return clamp(page, MIN_PAGE, count)


def paginate(items, page, size):
    """Return the items on the requested page.

    Requests beyond the final page fall back to the final page.
    """
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")
    size = valid_page_size(size)
    resolved = resolve_page(page, len(items), size)
    start = (resolved - 1) * size
    return list(items[start:start + size])


def last_page(items, size):
    """Return the items on the final page."""
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")
    count = page_count(len(items), size)
    if count == 0:
        return []
    return paginate(items, count, size)

"""Window slicing helpers that reuse the shared limits."""

from .limits import clamp, valid_page_size


def slice_window(items, start, size):
    """Return up to size items from start, clamped to the final window.

    A start value beyond the list falls back to the start of the final
    window so that the returned list keeps the requested window length.
    """
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")
    size = valid_page_size(size)
    if not items:
        return []
    last_start = max(0, len(items) - size)
    start = clamp(start, 0, last_start)
    return list(items[start:start + size])


def first_window(items, size):
    """Return the first size items."""
    return slice_window(items, 0, size)


def tail_window(items, size):
    """Return the final size items."""
    if not items:
        return []
    return slice_window(items, len(items) - 1, size)

"""Text rendering for paged output and progress bars."""

from .limits import as_int, clamp, valid_page_size
from .paginate import page_count, paginate


def format_progress(done, total, width=10):
    """Render progress as a filled bar followed by a ratio."""
    done = as_int(done, "done")
    total = as_int(total, "total")
    if total <= 0:
        raise ValueError("total must be positive")
    if done < 0:
        raise ValueError("done must not be negative")
    filled = clamp(round(width * done / total), 0, width)
    bar = "#" * filled + "-" * (width - filled)
    return f"[{bar}] {done}/{total}"


def format_page(items, page, size):
    """Render one page as numbered lines."""
    size = valid_page_size(size)
    entries = paginate(items, page, size)
    lines = [
        f"{index}. {entry}"
        for index, entry in enumerate(entries, start=1)
    ]
    return "\n".join(lines)


def format_summary(items, size):
    """Render the page count and item count of a collection."""
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")
    return f"items={len(items)} pages={page_count(len(items), size)}"


def format_ranges(total, size):
    """Render page ranges as a comma separated list."""
    from .chunks import page_ranges

    return ", ".join(f"{start}-{end}" for start, end in page_ranges(total, size))

